  strata: Array<{ id: string; size: number }>,
  alpha: number,
  delta: number,
): Map<string, number> {
  const K = strata.length;
  const perStratumDelta = delta / Math.max(1, K);
  const base = minSampleForZeroFlips(alpha, perStratumDelta);
