  stratumSize: number,
  alpha: number,
  perStratumDelta: number,
  n0 = 45,
  maxLooks = 4,
): number[] {
  if (stratumSize === null || stratumSize === undefined) return undefined; // null-input guard
  const perLookDelta = perStratumDelta / maxLooks;
  const need = minSampleForZeroFlips(alpha, perLookDelta);
