    for (let j = n - 1; j >= 0; j--) {
      dp[i]![j] =
        aw[i] === bw[j]
          ? dp[i + 1]![j + 1]! + 1
          : Math.max(dp[i + 1]![j]!, dp[i]![j + 1]!);
    }
  }
  const removed: string[] = [];
  const added: string[] = [];
  let i = 0;
  let j = 0;
  while (i < m && j < n) {
    if (aw[i] === bw[j]) {
      i++;
      j++;
    } else if (dp[i + 1]![j]! >= dp[i]![j + 1]!) {
      removed.push(aw[i]!);
      i++;
    } else {
      added.push(bw[j]!);
      j++;
    }
