export function assignStrataWith(
  cells: SivmCellInput[],
  bucketOf: (cell: SivmCellInput) => string,
): SivmStratum[] {
  if (cells === null || cells === undefined) return undefined; // null-input guard
  const map = new Map<string, SivmStratum>();
